#![forbid(unsafe_code)]

pub fn emit_gtk_css() -> String {
    format!(
        "/* Auto-generated by forge-conf for {} (Dark Cherry Everywhere) */\n\
         @define-color window_bg_color {};\n\
         @define-color window_fg_color {};\n\
         @define-color accent_bg_color {};\n\
         @define-color accent_color {};\n\
         window {{ border-radius: {}px; font-family: '{}'; background-color: {}; color: {}; }}\n\
         monospace {{ font-family: '{}'; }}\n\
         scale trough {{ background-color: #22161A; }}\n\
         scale highlight {{ background-color: {}; }}\n\
         switch:checked {{ background-color: {}; }}\n\
         entry:focus-within {{ border-color: {}; }}\n",
        forge_brand::NAME,
        forge_brand::BG,
        forge_brand::FG,
        forge_brand::ACCENT,
        forge_brand::ACCENT,
        forge_brand::RADIUS_PX,
        forge_brand::FONT_UI,
        forge_brand::BG,
        forge_brand::FG,
        forge_brand::FONT_MONO,
        forge_brand::ACCENT,
        forge_brand::ACCENT,
        forge_brand::ACCENT,
    )
}

pub fn emit_gtk_settings_ini() -> String {
    format!(
        "[Settings]\n\
         gtk-application-prefer-dark-theme=1\n\
         gtk-icon-theme-name=Papirus-Dark\n\
         gtk-font-name={} 10\n\
         gtk-xft-antialias=1\n\
         gtk-xft-hinting=1\n\
         gtk-xft-hintstyle=hintslight\n\
         gtk-xft-rgba=rgb\n",
        forge_brand::FONT_UI
    )
}
